try await database.transaction { db in
    let row = try await LockRecord.query(on: db)
        .filter(\.$lockable == key).first()
    guard row == nil || row?.owner == sessionID else {
        throw Abort(.conflict, reason: "locked by \(row!.owner)")
    }
    if row == nil {
        try await LockRecord(lockable: key, owner: sessionID,
                             acquiredAt: .now).save(on: db)
    }
}
